// Servidor de práctica (datos inventados). Express 5.3.0, solo escucha en 127.0.0.1.
const express = require('express');
const app = express();

const despachos = new Map([
  [42, { id: 42, cliente: 'Ferretería Norte', bultos: 12, estado: 'en ruta' }],
  [43, { id: 43, cliente: 'Kiosco Sur', bultos: 3, estado: 'nuevo' }],
]);

// Cuenta los pasos de UN pedido (res.locals es propio de cada pedido).
function paso(res, texto) {
  res.locals.n = (res.locals.n ?? 0) + 1;
  console.log(`  [${res.locals.n}] ${texto}`);
}

app.use((req, res, next) => {                       // eslabón 1: registrar
  console.log(`${req.method} ${req.originalUrl}`);
  paso(res, 'registrar: llegó el pedido');
  res.on('finish', () => paso(res, `registrar: salió ${res.statusCode}`));
  next();
});

app.use(express.json());                            // eslabón 2: leer el cuerpo JSON

app.use((req, res, next) => {                       // eslabón 3: sellar la hora
  req.llegada = Date.now();
  paso(res, 'sello: anoté la hora en req.llegada');
  next();
});

app.get('/despachos/:id', (req, res) => {           // ruta
  paso(res, `ruta GET /despachos/:id con id=${req.params.id}`);
  const d = despachos.get(Number(req.params.id));
  if (!d) return res.status(404).json({ error: 'no existe ese despacho' });
  res.json(d);
});

app.get('/despachos', (req, res) => {               // ruta
  paso(res, `ruta GET /despachos con consulta ${JSON.stringify(req.query)}`);
  let lista = [...despachos.values()];
  if (req.query.estado) lista = lista.filter((d) => d.estado === req.query.estado);
  res.json(lista);
});

app.post('/despachos', (req, res) => {              // ruta
  paso(res, `ruta POST /despachos con cuerpo ${JSON.stringify(req.body)}`);
  const { cliente, bultos } = req.body ?? {};
  if (typeof cliente !== 'string' || !Number.isInteger(bultos))
    return res.status(400).json({ error: 'faltan cliente o bultos' });
  const id = Math.max(...despachos.keys()) + 1;
  const d = { id, cliente, bultos, estado: 'nuevo' };
  despachos.set(id, d);
  res.status(201).location(`/despachos/${id}`).json(d);
});

app.get('/boom', async (req, res) => {              // ruta que falla a propósito
  paso(res, 'ruta GET /boom: lanzo un error');
