// Un «mini Express»: solo la cadena de middleware, sin red.
function crearApp() {
  const capas = [];
  return {
    use(fn) { capas.push(fn); },
    manejar(req, res) {
      let i = 0;
      const next = (err) => {
        const capa = capas[i++];
        if (!capa) return res.fin(err ? 500 : 404);   // se acabó la cadena
        try {
          if (err && capa.length === 4) capa(err, req, res, next);   // solo los de 4 parámetros ven errores
          else if (!err && capa.length < 4) capa(req, res, next);    // solo los de 3 o menos ven pedidos
          else next(err);                                            // los demás se saltean
        } catch (e) { next(e); }
      };
      next();
    },
  };
}

